package com.fasterxml.jackson.databind.jsontype.impl;

import com.fasterxml.jackson.annotation.JsonTypeInfo;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.type.TypeFactory;
import com.fasterxml.jackson.databind.util.ClassUtil;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ClassNameIdResolver._idFrom
 */
public class ClassNameIdResolver__idFrom_TriageGen2Test {

    private TypeFactory typeFactory;
    private TestableClassNameIdResolver resolver;
    private JavaType baseType;

    // Subclass to expose protected method and control _baseType
    private static class TestableClassNameIdResolver extends ClassNameIdResolver {
        public JavaType _baseType;

        public TestableClassNameIdResolver(JavaType baseType, TypeFactory typeFactory) {
            super(baseType, typeFactory);
            this._baseType = baseType;
        }

        @Override
        public JsonTypeInfo.Id getMechanism() {
            return JsonTypeInfo.Id.CLASS;
        }

        @Override
        public String idFromValue(Object value) {
            return null; // Not needed for testing _idFrom
        }

        @Override
        public String idFromValueAndType(Object value, Class<?> type) {
            return null; // Not needed for testing _idFrom
        }

        @Override
        public JavaType typeFromId(com.fasterxml.jackson.databind.DatabindContext context, String id) {
            return null;
        }

        @Override
        public String getDescForKnownTypeIds() {
            return null;
        }

        // Expose the protected method for testing
        public String callIdFrom(Object value, Class<?> cls, TypeFactory tf) {
            return _idFrom(value, cls, tf);
        }
    }

    enum TestEnum { A, B }

    abstract static class BaseEnum extends Enum<BaseEnum> {
        protected BaseEnum(String name) { super(name); }
    }
    static class SubEnum extends BaseEnum {
        SubEnum() { super("SUB"); }
    }

    static class Outer {
        static class Inner {}
    }

    @Before
    public void setUp() {
        ObjectMapper mapper = new ObjectMapper();
        typeFactory = mapper.getTypeFactory();
        baseType = typeFactory.constructType(Object.class);
        resolver = new TestableClassNameIdResolver(baseType, typeFactory);
    }

    @Test
    public void testStandardClass() {
        String result = resolver.callIdFrom(new Object(), String.class, typeFactory);
        assertEquals("java.lang.String", result);
    }

    @Test
    public void testEnumSubtype() {
        // If cls is an enum subclass, it should get the superclass (the base Enum)
        // Note: The logic says if (!cls.isEnum()) { cls = cls.getSuperclass(); }
        // This part of the code is slightly unusual but we test the branch.
        // Since SubEnum.class.isEnum() is true, it won't enter the if block.
        // But if we pass a class that 'is' an enum but isn't actually an enum (mocked/edge case), 
        // or if we pass BaseEnum.class (which is not an enum itself but a class extending Enum).

        String result = resolver.callIdFrom(null, BaseEnum.class, typeFactory);
        assertEquals(BaseEnum.class.getName(), result);
    }

    @Test
    public void testEnumDirect() {
        String result = resolver.callIdFrom(null, TestEnum.class, typeFactory);
        assertEquals(TestEnum.class.getName(), result);
    }

    @Test
    public void testEnumSet() {
        EnumSet<TestEnum> set = EnumSet.of(TestEnum.A);
        // The code uses ClassUtil.findEnumType. In standard Jackson, it finds the enum type.
        String result = resolver.callIdFrom(set, EnumSet.class, typeFactory);
        // Expected canonical form for EnumSet<TestEnum>
        assertEquals("java.util.EnumSet<com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen2Test$TestEnum>", result);
    }

    @Test
    public void testEnumMap() {
        EnumMap<TestEnum, Object> map = new EnumMap<>(TestEnum.class);
        String result = resolver.callIdFrom(map, EnumMap.class, typeFactory);
        // Expected canonical form for EnumMap<TestEnum, Object>
        assertEquals("java.util.EnumMap<com.fasterxml.jackson.databind.jsontype.impl.ClassNameIdResolver__idFrom_TriageGen2Test$TestEnum,java.lang.Object>", result);
    }

    @Test
    public void testArraysAsList() {
        List<String> list = Arrays.asList("a", "b");
        // Arrays.asList returns an internal class like java.util.Arrays$ArrayList
        String result = resolver.callIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testCollectionsWrapper() {
        List<String> list = Collections.singletonList("a");
        // Collections.singletonList returns java.util.Collections$SingletonList
        String result = resolver.callIdFrom(list, list.getClass(), typeFactory);
        assertEquals("java.util.ArrayList", result);
    }

    @Test
    public void testInnerClassWithBaseTypeMatch() {
        // Test the branch where cls is an inner class and baseType is the outer class
        JavaType outerType = typeFactory.constructType(Outer.class);
        resolver._baseType = outerType;

        String result = resolver.callIdFrom(new Outer.Inner(), Outer.Inner.class, typeFactory);
        assertEquals(Outer.class.getName(), result);
    }

    @Test
    public void testInnerClassWithoutBaseTypeMatch() {
        // Test the branch where cls is inner class but baseType is NOT the outer class
        JavaType differentType = typeFactory.constructType(String.class);
        resolver._baseType = differentType;

        String result = resolver.callIdFrom(new Outer.Inner(), Outer.Inner.class, typeFactory);
        assertEquals(Outer.Inner.class.getName(), result);
    }

    @Test
    public void testNonJavaUtilClass() {
        // Ensure non-java.util classes don't trigger the substring(9) logic
        String result = resolver.callIdFrom(new Object(), Integer.class, typeFactory);
        assertEquals("java.lang.Integer", result);
    }
}
